U.A("tv-async",'int[][] decades = new int[][]{\n        new int[]{1970, 1979},\n        new int[]{1980, 1989},\n        new int[]{1990, 1999},\n        new int[]{2000, 2009},\n        new int[]{2010, 2019},\n        new int[]{2020, 2029},\n        new int[]{2030, 2039},\n};\n\nFunction<Record, TreeViewItem> recordItem = record -> treeViewItem(Id.build(record.title))\n        .text(record.title + " (" + record.year + ")")\n        .icon(recordVinyl())\n        .addItems(record.tracks.asList(), track ->\n                treeViewItem(Id.build(record.title, String.valueOf(track.track)))\n                        .text(track.track + ". " + track.title)\n                        .icon(music())\n                        .addItems(track.writer(), writer ->\n                                treeViewItem(Id.build(record.title, String.valueOf(track.track), writer))\n                                        .text(writer)\n                                        .icon(edit())));\n\nTreeView treeView = treeView(selectableItems);\nreturn div()\n        .add(button("Reset all").css(util("mb-sm"))\n                .primary()\n                .onClick((e, b) -> treeView.reset()))\n        .add(treeView.addItems(asList(decades), decade ->\n                treeViewItem(Id.build("tv-async", String.valueOf(decade[0]), String.valueOf(decade[1])))\n                        .icon(folder())\n                        .expandedIcon(folderOpen())\n                        .store("range", decade)\n                        .text(decade[0] + " - " + decade[1])\n                        .addItems(item -> new Promise<>((resolve, reject) -> {\n                            int[] range = item.get("range");\n                            boolean boom = Math.random() < 0.25;\n                            int delay = new Random().nextInt(2000); // simulate remote call\n                            setTimeout(__ -> {\n                                if (boom) {\n                                    reject.onInvoke("Random error");\n                                } else {\n                                    resolve.onInvoke(records(r -> r.year >= range[0] && r.year <= range[1])\n                                            .stream()\n                                            .map(recordItem)\n                                            .collect(toList()));\n                                }\n                            }, delay);\n                        }))))\n        .element();');
U.A("truncate-default",'div().css("truncate-example-resize")\n        .add(truncate(LoremIpsum.words()))\n        .element()');U.A("truncate-middle",'div().css("truncate-example-resize")\n        .add(truncate("redhat_logo_black_and_white_reversed_simple_with_fedora_container.zip", middle))\n        .element()');U.A("truncate-start",'div().css("truncate-example-resize")\n        .add(truncate(LoremIpsum.words(), start))\n        .element()');U.A("truncate-max-chars",'String fullText = LoremIpsum.words();\nint maxChars = 20;\nString truncatedText = fullText.length() > maxChars\n        ? fullText.substring(0, maxChars) + "..."\n        : fullText;\nreturn div()\n        .add(truncate(truncatedText))\n        .element();');
